    std::filesystem::create_directories(dir);const auto path=dir/"input.wav";AudioBuffer audio;audio.sampleRate=48000;audio.channels={std::vector<float>(24000)};for(std::size_t i=0;i<24000;++i)audio.channels[0][i]=.08f*std::sin(i*.07);audio.channels[0][9001]=.75f;WavWriter::write(path,audio);
