    const float* rest[]={audio.channels[0].data()+2048};a.appendInput(10,2048,rest,21952);auto ready=a.getSnapshot();a.finishInput(10);auto final=a.getSnapshot();waiting.supplySnapshot(final);while(waiting.advance(sink)==SynthesisState::Produced){}
    check(waiting.frontier().state==SynthesisState::Finished&&published>0,"Final completion");waiting.cancel();check(waiting.advance(sink)==SynthesisState::Finished,"Completed EOS cancelled");rejects([&]{waiting.supplySnapshot(final);});check(waiting.frontier().state==SynthesisState::Finished,"Duplicate EOS corrupted completion");check(held->receivedInputFrames==2048&&!held->isFinal,"Old snapshot mutated");
    {ProgressiveAnalysisSession early(48000,1,10,{},{500000});early.appendInput(10,0,p,2048);early.finishInput(10);ProgressiveSynthesisEngine dsp(path,500000,10);rejects([&]{dsp.supplySnapshot(early.getSnapshot());});check(dsp.advance(sink)==SynthesisState::Failed,"Truncated analysis accepted as full-file EOS");}
    {ProgressiveSynthesisEngine wrong(path,500000,11);rejects([&]{wrong.supplySnapshot(final);});check(wrong.advance(sink)==SynthesisState::Failed,"Generation accepted");}
    {ProgressiveSynthesisEngine wrongSpeed(path,510000,10);rejects([&]{wrongSpeed.supplySnapshot(final);});check(wrongSpeed.advance(sink)==SynthesisState::Failed,"Unrequested speed accepted");}
    {ProgressiveSynthesisEngine duplicate(path,500000,10);duplicate.supplySnapshot(final);rejects([&]{duplicate.supplySnapshot(final);});check(duplicate.frontier().state==SynthesisState::Failed&&duplicate.frontier().published==0,"Duplicate pending EOS was not rejected");}
    {ProgressiveSynthesisEngine regressed(path,500000,10);regressed.supplySnapshot(final);rejects([&]{regressed.supplySnapshot(held);});check(regressed.advance(sink)==SynthesisState::Failed,"Regressed data accepted");}
    {ProgressiveSynthesisEngine cancelled(path,500000,10);cancelled.supplySnapshot(final);cancelled.cancel();check(cancelled.advance(sink)==SynthesisState::Cancelled&&cancelled.frontier().published==0,"Cancel before DSP published");}
    {ProgressiveSynthesisEngine* ptr=nullptr;unsigned calls=0;ProgressiveSynthesisEngine cancelled(path,500000,10,[&]{if(ptr&&++calls==2)ptr->cancel();});ptr=&cancelled;cancelled.supplySnapshot(final);check(cancelled.advance(sink)==SynthesisState::Cancelled,"Cancel during DSP");check(cancelled.frontier().generated>0&&cancelled.frontier().published==0,"Cancelled generated PCM escaped");}
    {std::atomic<bool> entered{false},release{false};ProgressiveSynthesisEngine* ptr=nullptr;unsigned calls=0;ProgressiveSynthesisEngine cancelling(path,500000,10,[&]{if(ptr&&++calls==2){entered.store(true);while(!release.load())std::this_thread::yield();}});ptr=&cancelling;cancelling.supplySnapshot(final);auto worker=std::async(std::launch::async,[&]{return cancelling.advance(sink);});while(!entered.load()&&worker.wait_for(std::chrono::milliseconds(0))!=std::future_status::ready)std::this_thread::yield();if(!entered.load())(void)worker.get();check(entered.load(),"DSP failed before cancellation barrier");cancelling.cancel();release.store(true);check(worker.get()==SynthesisState::Cancelled&&cancelling.frontier().generated>0&&cancelling.frontier().published==0,"Cross-thread cancel before commit published PCM");}
