    {auto cancelled=std::make_shared<AnalysisSnapshot>(*ready);cancelled->isCancelled=true;ProgressiveSynthesisEngine x(path,500000,10);x.supplySnapshot(cancelled);check(x.advance(sink)==SynthesisState::Cancelled,"Analysis cancellation became EOS");rejects([&]{x.supplySnapshot(ready);});check(x.advance(sink)==SynthesisState::Cancelled,"Old normal snapshot restarted cancelled analysis");}
    {auto run=[&](std::uint64_t gen){PinnedInput input(path,gen);ProgressiveAnalysisSession analysis(48000,1,gen,{},{500000});ProgressiveSynthesisEngine dsp(input.dspPath(),500000,gen,[&]{input.validate(analysis);});while(input.appendNext(analysis,5003)){}input.finish(analysis);dsp.supplySnapshot(analysis.getSnapshot());std::vector<float> out;auto s=[&](auto g,auto offset,auto block,auto n){check(g==gen&&offset==out.size(),"Independent session contaminated");out.insert(out.end(),block[0],block[0]+n);};while(dsp.advance(s)==SynthesisState::Produced){}return out;};auto one=std::async(std::launch::async,[&]{return run(20);});auto two=std::async(std::launch::async,[&]{return run(21);});const auto first=one.get(),second=two.get();check(first.size()==second.size(),"Parallel frame counts differ");for(std::size_t i=0;i<first.size();++i)check(std::bit_cast<std::uint32_t>(first[i])==std::bit_cast<std::uint32_t>(second[i]),"Parallel same-input PCM bits differ");}
